sql_calls.sql:
SELECT SUM(units) AS total_units_ordered
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT *
FROM store.stock_counts
LIMIT 20;

SELECT *
FROM payments.pos_payments
LIMIT 20;

SELECT sku, name, price_inr
FROM store.products
WHERE name ILIKE '%milk%' OR sku ILIKE '%milk%';

SELECT DISTINCT reason
FROM store.write_offs
ORDER BY reason;

SELECT DISTINCT bill_id
FROM payments.pos_payments
LIMIT 10;

SELECT sku, name
FROM store.products
WHERE name ILIKE '%bag%' OR name ILIKE '%carry%';

SELECT sku, name
FROM store.products
LIMIT 50;

SELECT sku, name
FROM store.products
WHERE name ILIKE '%bag%' OR name ILIKE '%carry%' OR name ILIKE '%plastic%' OR name ILIKE '%paper%';

SELECT *
FROM payments.customer_complaints
WHERE kind ILIKE '%bag%' OR kind ILIKE '%carry%' OR resolution ILIKE '%bag%' OR resolution ILIKE '%carry%';

SELECT *
FROM payments.pos_payments
WHERE note ILIKE '%bag%' OR note ILIKE '%carry%';

SELECT *
FROM store.daily_sales
LIMIT 10;

SELECT DISTINCT sku_scanned
FROM store.pos_lines
ORDER BY sku_scanned;

SELECT DISTINCT till_status
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT MIN(ts::date) as min_date, MAX(ts::date) as max_date, COUNT(DISTINCT bill_id) as bill_count
FROM payments.pos_payments
WHERE ts >= '2026-05-01' AND ts < '2026-07-01';

SELECT MIN(date) as min_date, MAX(date) as max_date, COUNT(*) as row_count
FROM store.daily_sales
WHERE date >= '2026-05-01' AND date < '2026-07-01';

SELECT COUNT(*) as row_count
FROM store.fresh_deliveries
WHERE route = 'R-07' AND delivery_ts >= '2026-06-01' AND delivery_ts < '2026-07-01';

SELECT COUNT(*) as row_count
FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01';

SELECT COUNT(DISTINCT bill_id) as bill_count, SUM(amount_inr) as total_revenue, AVG(amount_inr) as avg_bill_value
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT COUNT(DISTINCT bill_id) as bill_count, SUM(amount_inr) as total_revenue, AVG(amount_inr) as avg_bill_value
FROM payments.pos_payments
WHERE ts >= '2026-05-01' AND ts < '2026-07-01';

SELECT MIN(ts::date) as min_date, MAX(ts::date) as max_date, COUNT(DISTINCT bill_id) as bill_count
FROM payments.pos_payments
WHERE ts >= '2026-05-01' AND ts < '2026-06-01';

SELECT * FROM store.goods_receipts
WHERE received_ts >= '2026-06-12' AND received_ts < '2026-06-13'
  AND asn_sku LIKE '%RICE%';

SELECT * FROM store.store_orders
WHERE order_id IN (
    SELECT DISTINCT order_id FROM warehouse.shipping_notice_lines
    WHERE shipment_id IN (
        SELECT shipment_id FROM store.goods_receipts
        WHERE received_ts >= '2026-06-12' AND received_ts < '2026-06-13'
          AND asn_sku = 'RICE-SM-5KG'
    )
);

SELECT * FROM store.inventory_book
WHERE sku = 'RICE-SM-5KG' AND date >= '2026-06-01' AND date < '2026-07-01'
ORDER BY date;

SELECT SUM(units_sold) AS total_units_june_2026
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT sku, name
FROM store.products
WHERE name ILIKE '%bread%';

SELECT COUNT(DISTINCT bill_id) AS bills_march_2026
FROM payments.pos_payments
WHERE ts >= '2026-03-01' AND ts < '2026-04-01';
